		r.Diagnostics = append(r.Diagnostics, unicodeGeneratedDiagnosticOf(s, unicodeGeneratedIssue{"lang.golang.no-effective-input", "the selected property has no effective execution", nil}))
		r.Passed = false
		r.Infrastructure = true
