			r.Passed = false
			message := fmt.Sprintf("the 95th percentile %s exceeds within %s", r.durations[i], s.Within)
			r.Differences = append(r.Differences, message)
			r.Diagnostics = append(r.Diagnostics, unicodeGeneratedDiagnosticOf(s, unicodeGeneratedIssue{"lang.golang.within-exceeded", message, nil}))
